// ====================================================================
// EDITE AQUI: troque pelo JID do SEU grupo de WhatsApp.
// Descubra o JID via GET /group/fetchAllGroups na sua instância
// Evolution API/WAHA, ou peça pro bot te mandar o remoteJid da primeira
// mensagem recebida antes de configurar o filtro.
// ====================================================================
const GROUP_JID = 'COLOQUE_O_JID_DO_SEU_GRUPO_AQUI@g.us';

const item = $input.first().json;
const data = item.body?.data || item.data || item;

const remoteJid = data.key?.remoteJid;
const fromMe = data.key?.fromMe;

if (remoteJid !== GROUP_JID) {
  return [];
}

const texto = data.message?.conversation
  || data.message?.extendedTextMessage?.text
  || '';

if (!texto) {
  return [];
}

// Ajuste este filtro se você quiser capturar suas próprias mensagens no
// grupo (ver README, seção "Filtro de mensagens próprias") — por padrão,
// mensagens enviadas pelo próprio número conectado são ignoradas.
if (fromMe === true) {
  return [];
}

const urlRegex = /(https?:\/\/[^\s]+)/g;
const links = (texto.match(urlRegex) || []).join(', ');

const remetenteJid = data.key?.participant || data.key?.remoteJid || '';
const remetenteNome = data.pushName || remetenteJid;

const rawTs = data.messageTimestamp;
const ts = typeof rawTs === 'string' ? parseInt(rawTs, 10) : rawTs;
const timestampIso = new Date(ts * 1000).toISOString();

return [{
  json: {
    remetente_nome: remetenteNome,
    remetente_jid: remetenteJid,
    texto,
    links,
    timestamp: timestampIso,
  },
}];
